 budget_ms=1200 if index<94 else 6000
 checkpoint=Path(f'{prefix}-{index}-pair.json')
 if checkpoint.exists():
  pair=json.loads(checkpoint.read_text());assert pair['binarySha256']==expected and pair['line']==line
