  for side in sides:
   path=f'{prefix}-{index}-{side}'
   with open(path+'.txt','w') as out:
    result=subprocess.run(['python3','/tmp/chess-oct10-idle-run.py',binaries[side],'abdada-bench','--fens',str(fenfile),'--think-ms',str(budget_ms),'--threads','4','--runs','1','--json',path+'.json'],stdout=out,stderr=subprocess.STDOUT)
   if result.returncode in (75,130):
