   if result.returncode:raise RuntimeError(f'Benchmark failed {index} {side}: {result.returncode}')
   pair[side]=json.loads(Path(path+'.json').read_text())['positions'][0]
  if interrupted:continue
  checkpoint.write_text(json.dumps(pair,indent=2)+'\n');records.append(pair)
  print('Completed pair',index+1,'of',len(lines),pair['before']['threads'][0]['summary']['move'],pair['after']['threads'][0]['summary']['move'],flush=True)
  break
for side in binaries:
 Path(prefix+'-'+side+'.json').write_text(json.dumps({'metadata':meta,'positions':[r[side] for r in records]},indent=2)+'\n')
while True:
 wait_idle()
